package br.com.onda;
import android.content.*;import android.database.Cursor;import android.database.sqlite.*;import android.net.Uri;import java.util.*;import java.security.MessageDigest;import java.nio.charset.StandardCharsets;import java.io.*;
/** Private transactional index. Old results survive cancellation or extraction failure. */
@androidx.media3.common.util.UnstableApi
final class MemoryStore extends SQLiteOpenHelper {
 static final class Source {final String id,uri,sidecar,name,kind,stamp;Source(String id,String uri,String sidecar,String name,String kind,String stamp){this.id=id;this.uri=uri;this.sidecar=sidecar;this.name=name;this.kind=kind;this.stamp=stamp;}}
 static final class Hit {final long id,start,end;final int page;final String tag,text;final Source source;final boolean favorite;Hit(Cursor c){id=c.getLong(0);start=c.getLong(1);end=c.getLong(2);page=c.getInt(3);text=c.getString(4);tag=c.getString(5);source=new Source(c.getString(6),c.getString(7),c.getString(8),c.getString(9),c.getString(10),c.getString(11));favorite=c.getInt(12)!=0;}}
 MemoryStore(Context c){super(c,"multimedia-memory.db",null,1);}
 public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE sources(id TEXT PRIMARY KEY,uri TEXT,sidecar TEXT,name TEXT,kind TEXT,stamp TEXT)");db.execSQL("CREATE TABLE segments(id INTEGER PRIMARY KEY AUTOINCREMENT,sid TEXT,start INTEGER,end INTEGER,page INTEGER,body TEXT,tag TEXT UNIQUE)");db.execSQL("CREATE INDEX by_source ON segments(sid)");db.execSQL("CREATE TABLE stars(tag TEXT PRIMARY KEY,sid TEXT)");db.execSQL("CREATE VIRTUAL TABLE words USING fts4(body, tokenize=unicode61)");}
 public void onUpgrade(SQLiteDatabase db,int old,int next){throw new IllegalStateException("Migração indisponível");}
 static String key(String text){try{byte[] hash=MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();for(byte b:hash){s.append(Character.forDigit((b>>4)&15,16));s.append(Character.forDigit(b&15,16));}return s.toString();}catch(Exception e){throw new IllegalStateException(e);}}
 static Source source(Context c,Uri uri,Uri sidecar,String name,String kind){return new Source(key(kind+"\n"+uri+"\n"+sidecar),uri.toString(),sidecar==null?"":sidecar.toString(),name,kind,AudioChapterStore.stamp(c,uri));}
 List<Source> sources(){List<Source> out=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT id,uri,sidecar,name,kind,stamp FROM sources ORDER BY name",null)){while(c.moveToNext())out.add(new Source(c.getString(0),c.getString(1),c.getString(2),c.getString(3),c.getString(4),c.getString(5)));}return out;}
 interface Extract {void run(Writer writer)throws Exception;}
 final class Writer {private final Source source;private int count;Writer(Source source){this.source=source;}void add(MemoryText.Cue cue)throws IOException{if(cue.text.isEmpty())return;if(++count>100000)throw new IOException("Muitos trechos neste arquivo; divida-o antes de indexar.");SQLiteDatabase db=getWritableDatabase();String tag=key(source.id+"\n"+cue.page+"\n"+cue.start+"\n"+cue.end+"\n"+cue.text);ContentValues row=new ContentValues();row.put("sid",source.id);row.put("start",cue.start);row.put("end",cue.end);row.put("page",cue.page);row.put("body",cue.text);row.put("tag",tag);long id=db.insertWithOnConflict("segments",null,row,SQLiteDatabase.CONFLICT_IGNORE);if(id!=-1){ContentValues words=new ContentValues();words.put("rowid",id);words.put("body",SearchText.normalize(cue.text));db.insertOrThrow("words",null,words);}}int count(){return count;}}
 int replace(Source source,Extract extract)throws Exception{SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{eraseRows(db,source.id);Writer writer=new Writer(source);extract.run(writer);if(writer.count()==0)throw new IOException("Nenhum texto encontrado. PDFs de imagem precisam de OCR; legendas precisam de horários SRT/VTT.");ContentValues values=new ContentValues();values.put("id",source.id);values.put("uri",source.uri);values.put("sidecar",source.sidecar);values.put("name",source.name);values.put("kind",source.kind);values.put("stamp",source.stamp);db.insertWithOnConflict("sources",null,values,SQLiteDatabase.CONFLICT_REPLACE);db.setTransactionSuccessful();return writer.count();}finally{db.endTransaction();}}
 private void eraseRows(SQLiteDatabase db,String id){db.execSQL("DELETE FROM words WHERE rowid IN (SELECT id FROM segments WHERE sid=?)",new Object[]{id});db.delete("segments","sid=?",new String[]{id});}
 void remove(String id){SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{eraseRows(db,id);db.delete("stars","sid=?",new String[]{id});db.delete("sources","id=?",new String[]{id});db.setTransactionSuccessful();}finally{db.endTransaction();}}
 void favorite(Hit hit){ContentValues row=new ContentValues();row.put("tag",hit.tag);row.put("sid",hit.source.id);if(hit.favorite)getWritableDatabase().delete("stars","tag=?",new String[]{hit.tag});else getWritableDatabase().insertWithOnConflict("stars",null,row,SQLiteDatabase.CONFLICT_IGNORE);}
 private static final String SELECT="SELECT s.id,s.start,s.end,s.page,s.body,s.tag,d.id,d.uri,d.sidecar,d.name,d.kind,d.stamp,CASE WHEN f.tag IS NULL THEN 0 ELSE 1 END FROM segments s JOIN sources d ON d.id=s.sid LEFT JOIN stars f ON f.tag=s.tag ";
 List<Hit> search(String raw,boolean favorites){String query=MemoryText.query(raw);List<Hit> out=new ArrayList<>();if(!favorites&&query.isEmpty())return out;String sql=SELECT+(query.isEmpty()?"":"JOIN words ON words.rowid=s.id ")+"WHERE "+(favorites?"f.tag IS NOT NULL":"1=1")+(query.isEmpty()?"":" AND words MATCH ?")+" ORDER BY d.name,s.page,s.start,s.id LIMIT 100";try(Cursor c=getReadableDatabase().rawQuery(sql,query.isEmpty()?null:new String[]{query})){while(c.moveToNext())out.add(new Hit(c));}return out;}
 Hit tag(String tag){try(Cursor c=getReadableDatabase().rawQuery(SELECT+"WHERE s.tag=?",new String[]{tag})){return c.moveToFirst()?new Hit(c):null;}}
}
